import atexit, gc, platform, weakref
class Cleanupper:
    def __init__(self):
        self.atexit_fns = []
        weakref.finalize(self, self._shutdown)
    def register_atexit(self, fn):
        self.atexit_fns.append(fn)
    def unregister_atexit(self, fn):
        if fn in self.atexit_fns:
            self.atexit_fns.remove(fn)
    def _shutdown(self):
        for fn in self.atexit_fns:
            fn()
        self.atexit_fns = []
def say(s): print(s, flush=True)
say(platform.python_implementation()+' '+platform.python_version())
atexit.register(say, 'ordinary earlier')
def main():
    c = Cleanupper()
    c.register_atexit(lambda: say('cleanup first'))
    removed = lambda: say('unexpected removed callback')
    c.register_atexit(removed)
    c.unregister_atexit(removed)
    c.register_atexit(lambda: say('cleanup second'))
    return weakref.ref(c)
ref = main()
gc.collect()
say('after main; retained: '+str(ref() is not None))
atexit.register(say, 'ordinary later')
failed = Cleanupper()
def fail():
    say('failing callback')
    raise ValueError('test callback')
